    text-transform: uppercase;
    color: var(--primary-color);
}

.footer-col ul li {
    margin-bottom: 10px;
    font-size: 14px;
}

.footer-col a {
    color: var(--text-color);
}

.footer-bottom {
    border-top: 1px solid #e0e0e0;
    padding-top: 20px;
    text-align: center;
    font-size: 12px;
    color: var(--light-text);
}

/* Responsive */
@media (max-width: 768px) {
    .header-content {
        padding: 0 15px;
    }

    nav {
        display: none;
    }

    .categories-grid {
        grid-template-columns: 1fr;
    }

    .about-content, .product-detail {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}
